    const f = rand()
    const a = strip[k]
    const b = inner[k]
    const p = [a[0] + (b[0] - a[0]) * (0.15 + f * 0.85) + (rand() - 0.5) * 4, a[1] + (b[1] - a[1]) * (0.15 + f * 0.85) + (rand() - 0.5) * 4]
    if (rand() < Math.pow(1 - f, 1.4) * 0.9) dots += dot(p)
    else if (rand() < 0.05) glints += line([[p[0] - 1.6, p[1]], [p[0] + 1.6, p[1]]]) + line([[p[0], p[1] - 1.6], [p[0], p[1] + 1.6]])
