function clearing(cx, cy, rx, ry, seed, n = 18) {
  const rand = rng(seed)
  const out = []
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2
    const k = 0.9 + rand() * 0.18
    out.push([r1(cx + Math.cos(a) * rx * k), r1(cy + Math.sin(a) * ry * k)])
  }
  return out
}
