/** 단계 집합을 정확히 나누는 가장 적은 문 — 겹치지 않는 문들 (한 단계에 한 벌만 그려진다). 문은 열쇠마다 없음·true·false 의 3^5 가지 */
const COVER = (() => {
  let all = [{}]
  for (const [k] of GATE_N) all = all.flatMap((g) => [g, { ...g, [k]: true }, { ...g, [k]: false }])
  const mask = (g) => LEVELS.reduce((m, l) => (inPhase(g, l) ? m | (1 << l) : m), 0)
  const keys = (g) => Object.keys(g).length
  const one = new Map()
  for (const g of all) {
    const m = mask(g)
    if (m && (!one.has(m) || keys(g) < keys(one.get(m)))) one.set(m, g)
  }
  const best = new Map([[0, []]])
  const cost = (gs) => gs.length * 100 + gs.reduce((s, g) => s + keys(g), 0)
  for (let m = 1; m < 1 << LEVELS.length; m++) {
    const low = m & -m
    let pick = null
    for (const [sm, g] of one) {
      if (!(sm & low) || (sm & ~m) !== 0) continue
      const rest = best.get(m & ~sm)
      if (!rest) continue
      const gs = [g, ...rest]
      if (!pick || cost(gs) < cost(pick)) pick = gs
    }
    if (pick) best.set(m, pick)
  }
  return (levels) => {
    const m = levels.reduce((a, l) => a | (1 << l), 0)
    const gs = best.get(m)
    if (!gs) throw new Error(`단계 ${levels.join('·')} 를 나누는 문이 없다`)
    // 문은 맞는 가장 낮은 단계 차례로
    const first = (g) => LEVELS.find((l) => inPhase(g, l))
    return [...gs].sort((a, b) => first(a) - first(b)).map((g) => ({ ...g }))
  }
})()

/**
 * 페이즈별 모습을 한 parts 로. 원래 부분(lv 없음)은 예전 compact(바로 이웃한 같은 칠·같은 문은 한 path)처럼 묶고, 묶음마다 단계별로 그려지는 부분을 본다 —
 * 원래 부분이 다 그려지고 새 부분이 끼지 않는 단계에서는 예전 묶음 그대로(같은 d) 한 벌, 나머지 단계에서는 그 단계에 그려지는 부분(새 부분 포함)을
 * 다시 묶은 벌을 그 자리에 둔다. 묶음 밖의 새 부분은 제자리에. 단계마다 한 벌만 그려지므로 칠 차례는 늘 원래 차례다.
 */
function merge(list) {
  const GK = ['phase', 'phase2', 'phase3', 'phase4', 'phase5']
  const key = (p) => GK.map((g) => String(p[g])).join()
  const levelsOf = (p) => (p.lv ? p.lv.filter((l) => inPhase(p, l)) : LEVELS.filter((l) => inPhase(p, l) && !(p.off ?? []).includes(l)))
  const raw = list.filter((p) => p.d)
  for (const p of raw) if (p.lv && p.lv.includes(0)) throw new Error('끔(0)의 그림은 원래 그림 그대로 — 새 부분을 끔에 그리지 않는다')
  for (const p of raw) if (p.off && p.off.includes(0)) throw new Error('끔(0)의 그림은 원래 그림 그대로 — 원래 부분을 끔에서 빼지 않는다')
  const groups = []
  const owner = raw.map(() => -1)
  // 묶음은 원래 부분의 차례로 이어진다 — 사이의 새 부분은 묶음을 끊지 않는다(예전에는 없었다)
  raw.forEach((p, i) => {
    if (p.lv) return
    const g = groups.at(-1)
    if (g && g.cls === p.cls && g.key === key(p)) g.members.push(i)
    else groups.push({ cls: p.cls, key: key(p), members: [i] })
  })
  groups.forEach((g, gi) => {
    for (let i = g.members[0]; i <= g.members.at(-1); i++) owner[i] = gi
  })
  const seq = (ps) => {
    const out = []
    for (const p of ps) {
      const last = out.at(-1)
      if (last && last.cls === p.cls) last.d += p.d
      else out.push({ cls: p.cls, d: p.d })
    }
    return out
  }
  const out = []
  const emit = (items, levels) => {
    for (const g of COVER(levels)) for (const it of items) out.push({ cls: it.cls, d: it.d, ...g })
  }
  let i = 0
  while (i < raw.length) {
    if (owner[i] < 0) {
      // 묶음 밖의 새 부분 — 같은 칠·같은 단계가 이웃하면 한 path 로
      let j = i
      while (j + 1 < raw.length && owner[j + 1] < 0 && raw[j + 1].cls === raw[i].cls && String(levelsOf(raw[j + 1])) === String(levelsOf(raw[i]))) j++
      const lv = levelsOf(raw[i])
      if (lv.length) emit([{ cls: raw[i].cls, d: raw.slice(i, j + 1).map((p) => p.d).join('') }], lv)
      i = j + 1
      continue
    }
    const g = groups[owner[i]]
    const span = raw.slice(g.members[0], g.members.at(-1) + 1)
    const whole = []
    const variants = new Map()
    for (const l of LEVELS) {
      const drawn = span.filter((p) => levelsOf(p).includes(l))
      if (!drawn.length) continue
      if (drawn.length === g.members.length && drawn.every((p) => !p.lv)) whole.push(l)
      else {
        const s = seq(drawn)
        const k = JSON.stringify(s)
        if (!variants.has(k)) variants.set(k, { s, levels: [] })
        variants.get(k).levels.push(l)
      }
    }
    if (whole.length) emit([{ cls: g.cls, d: g.members.map((m) => raw[m].d).join('') }], whole)
    for (const v of variants.values()) emit(v.s, v.levels)
    i = g.members.at(-1) + 1
  }
  return out
}

